/*
 * AC POWER ON/OFF IR database
 * Source: Flipper-IRDB (ACs/)
 * Extracted power, power-on, power-off, on/off and standby signals.
 *
 * Entries: 209 signals from 153 AC remote files
 *   RAW captures: 164
 *   Parsed NEC / NECext converted to mark/space timings: 45
 *
 * Timing values are stored in 10-us units, matching the TV-B-Gone sender.
 * Raw captures are preserved as pulse timings (quantized to 10 us).
 * This file is standalone and does not modify NA_EU-236.h or CUSTOM_CODES-1245.h.
 *
 * Include after global.h / with the project's IrCode definition available.
 */

#include "global.h"


